('. It keeps working without signal and sends your position to dispatch. The call closes when your report is filed.', 'nso', '. E tšwela pele go šoma ntle le signal gomme e romela lefelo la gago go baromedi. Mogala o tswalelwa ge pego ya gago e romeletšwe.'),
