('A call comes here once its officer files the report. Read the case file, then close it.', 'nso', 'Mogala o tla mo ge mohlankedi wa wona a rometše pego. Bala faele ya molato, ke moka o e tswalele.'),
('A call sign is one patrol post, such as ALPHA 12.', 'nso', 'Leswao la go bitša ke boemo bo tee bja patrol, bjalo ka ALPHA 12.'),
('A court date keeps the person off the roster that day.', 'nso', 'Letšatšikgwedi la kgorotsheko le dira gore motho a se be lenaneong la mošomo letšatšing leo.'),
('A danger that cannot wait?', 'nso', 'Kotsi yeo e ka se emego?'),
('A failed check prevents sign-on. Filing this inspection will take the appliance out of service and notify command.', 'nso', 'Teko ye e paletšwego e thibela go tsena mošomong. Go romela tlhahlobo ye go tla ntšha sedirišwa mošomong le go tsebiša balaodi.'),
('A failed check sends the bodycam for repair. You will need to choose another one, or say why you have none.', 'nso', 'Teko ye e paletšwego e romela khamera ya mmele go lokišwa. O tla swanela go kgetha ye nngwe, goba o bolele gore ke ka lebaka la eng o se na yona.'),
('A failed safety check or damage sends the firearm to the armourer. You will need to select another one.', 'nso', 'Teko ya polokego ye e paletšwego goba tshenyo e romela sethunya go molaodi wa dibetša. O tla swanela go kgetha se sengwe.'),
('A failed vehicle check takes the ambulance off the road when you file. Continue to the stock check and describe the fault there.', 'nso', 'Tlhahlobo ya koloi yeo e paletšego e tloša ambulansi tseleng ge o romela. Tšwela pele go tlhahlobo ya setoko gomme o hlalose phošo moo.'),
('A fake location app is on. Turn it off: your position cannot be used and your supervisor is told.', 'nso', 'App ya lefelo la maaka e bulegile. E time: boemo bja gago bo ka se šomišwe gomme molebeledi wa gago o a botšwa.'),
('A fault on the last notice was still there.', 'nso', 'Phošo yeo e begilwego tsebišong ya mafelelo e sa le gona.'),
('A fault on the last notice was still there. Consider a fine or court (s.79).', 'nso', 'Phošo yeo e begilwego tsebišong ya mafelelo e sa le gona. Nagana ka faene goba kgorotsheko (s.79).'),
('A home', 'nso', 'Legae'),
