('A month at a time: shift patterns that repeat for a team.', 'nso', 'Kgwedi e tee ka nako: dipaterone tša shift tšeo di boeletšwago sehlopheng.'),
('A patient’s severity is their own: the incident can be Critical while the patient has minor injuries.', 'nso', 'Bošoro bja molwetši ke bja gagwe: tiragalo e ka ba ye Bohlokwa kudu mola molwetši a na le dikgobalo tše nnyane.'),
