on conflict (key, lang) do update
   set text = excluded.text, status = 'approved', drafted_by = 'criti', updated_by_name = excluded.updated_by_name,
       updated_at = now(), approved_by = null, approved_by_name = excluded.approved_by_name, approved_at = now()
 where not (t.status = 'approved' and t.drafted_by = 'person');

insert into public.translations as t (key, lang, text, status, drafted_by, updated_by_name, updated_at, approved_by_name, approved_at)
select v.key, v.lang, v.text, 'approved', 'criti', 'Claude', now(), 'Claude (auto-approved)', now()
from (values
('Answer all six readiness questions.', 'nso', 'Araba dipotšišo tšohle tše tshela tša go itokiša.'),
('Answer every question honestly.', 'nso', 'Araba potšišo ye nngwe le ye nngwe ka botshepegi.'),
('Answer every question honestly. Your answers and submission time are recorded for supervisor review. Questions marked', 'nso', 'Araba potšišo ye nngwe le ye nngwe ka botshepegi. Dikarabo tša gago le nako ya go romela di a ngwalwa gore molaodi a di lekole. Dipotšišo tše di swailwego'),
('Any', 'nso', 'Efe goba efe'),
