('EVIDENCE ({n})', 'nso', 'BOHLATSE ({n})'),
('Each call sign is a row: pick the member for it.', 'nso', 'Leswao le lengwe le le lengwe la go bitša ke mothalo: kgetha setho sa lona.'),
('Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.', 'nso', 'Leswao le lengwe le le lengwe la go bitša ke sebaka se tee sa mošomo: moo le patrolago gona, diiri tša lona, khefu ya lona le maemo ao le a nyakago. Kabo ya Mošomo e bea bašomi go tše.'),
('Each call sign with its area, hours and the rank it needs.', 'nso', 'Leswao le lengwe le le lengwe la go bitša le lefelo la lona, diiri le maemo ao le a nyakago.'),
('Each day''s reports, by where they stand.', 'nso', 'Dipego tša letšatši le lengwe le le lengwe, go ya ka moo di lego gona.'),
('Each link or code works once and expires after {invitationTtlHours} hours. Sending again cancels the old one.', 'nso', 'Lehlakanyo goba khoutu ye nngwe le ye nngwe e šoma gatee gomme e fela ka morago ga diiri tše {invitationTtlHours}. Go romela gape go khansela ya kgale.'),
('Each member’s record as the old system kept it: numbers, rank, station, section, weekend group, contacts, LEO record and screen access.', 'nso', 'Rekoto ya setho se sengwe le se sengwe bjalo ka ge tshepedišo ya kgale e e bolokile: dinomoro, maemo, seteišene, karolo, sehlopha sa mafelelo a beke, dikgokagano, rekoto ya LEO le phihlelelo ya sekrine.'),
('Each patient and how bad they are', 'nso', 'Molwetši yo mongwe le yo mongwe le gore o gobetše gakaakang'),
('Each person gets their own invitation, as their confirmed role, by the route shown: email where HR gave an address, SMS where there is only a cellphone{value}, otherwise a printed code. Each link or code works once and expires after its set time.', 'nso', 'Motho yo mongwe le yo mongwe o hwetša taletšo ya gagwe, bjalo ka mošomo wa gagwe wo o netefaditšwego, ka tsela ye e bontšhitšwego: imeile moo HR e filego aterese, SMS moo go nago le selefouno fela{value}, go sego bjalo khoutu ye e gatišitšwego. Lehlakanyo goba khoutu ye nngwe le ye nngwe e šoma gatee gomme e fela ka morago ga nako ya yona ye e beilwego.'),
('Each rule acts at most once per thing per threshold — a call that breaches its SLA raises one alert at each tier, not one every five minutes. Thresholds are stored per rule, so changing “escalate after 10 minutes” to 15 needs no deployment. Every change and every manual run is written to the audit trail with your name on it.', 'nso', 'Molao o mongwe le o mongwe o dira gatee fela selong se sengwe le se sengwe moedising o mongwe le o mongwe — mogala wo o fetago SLA ya wona o tsoša temošo e tee maemong a mangwe le a mangwe, e sego e tee metsotso ye mengwe le ye mengwe ye mehlano. Meedi e bolokwa ka molao o mongwe le o mongwe, ka fao go fetoša "oketša morago ga metsotso ye 10" go ya go 15 ga go nyake go tsenywa. Phetogo ye nngwe le ye nngwe le go dirwa go gongwe le go gongwe ka seatla go ngwalwa mohlaleng wa tlhakišišo le leina la gago.'),
('Each service''s identity — crest, colours and naming — as it appears across the platform, the responder app and printed reports.', 'nso', 'Boitsebišo bja tirelo ye nngwe le ye nngwe — leswao, mebala le maina — bjalo ka ge bo bonagala sethaleng ka moka, go app ya baarabi le dipegong tše di gatišitšwego.'),
