('Emergency lights & siren functioning', 'nso', 'Mabone a tšhoganetšo le seirene di a šoma'),
('Emergency — hold to call for assistance', 'nso', 'Tšhoganetšo — swara go kgopela thušo'),
('Emergency-flagged rows are highlighted. Resolve inline once handled.', 'nso', 'Methaladi ye e swailwego bjalo ka tšhoganetšo e a bonagatšwa. E rarolle mo ge e šetše e šongwa.'),
('Emotional Wellbeing (Feeling mentally balanced?)', 'nso', 'Boiketlo bja maikutlo (O ikwa o lekalekane monaganong?)'),
('Employee', 'nso', 'Mošomi'),
('Employee name', 'nso', 'Leina la mošomi'),
('Employment status', 'nso', 'Maemo a mošomo'),
('Emulators and simulators cannot register for push. Alerts still arrive while the app is open.', 'nso', 'Di-emulator le di-simulator di ka se ngwadišetše ditsebišo. Ditemošo di sa fihla mola app e butšwe.'),
('En Route', 'nso', 'O tseleng'),
('En route', 'nso', 'O tseleng'),
('Enabled', 'nso', 'Go butšwe'),
('Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.', 'nso', 'Go bula sebopego ga go fe mošomo selo seo matrix ya ditsela le polokego ya maemo a mothaladi di bego di ka se se dumelele — ditshepedišo tše pedi di šoma mmogo. Go tima se tee go se uta gohle gomme go dira gore ditsela tša sona tša sebele di gane, mohiring wo fela.'),
