('Ending a shift in the app is not switched on for this server yet. Hand your kit in at the counter and tell your supervisor.', 'nso', 'Go fetša šifi ka app ga se go bulwe sebeleng se. Nea didirišwa tša gago khaontareng gomme o botše molaodi wa gago.'),
