('I am not drawing a firearm this shift (e.g. mine is not on the armoury register). This is recorded on my start-of-shift record.', 'nso', 'Ga ke tšee sethunya šifiting ye (mohl. sa ka ga se gona rejisetareng ya ntlo ya dibetša). Se se ngwadilwe rekhoteng ya ka ya go thoma šifiti.'),
('I am not wearing a bodycam this shift. My reason is on my start-of-shift record and my supervisor sees it.', 'nso', 'Ga ke apare khamera ya mmele šifiting ye. Lebaka la ka le rekhoteng ya ka ya go thoma šifiti gomme mohlokomedi wa ka o a le bona.'),
('I checked this ambulance and its stock myself, and the answers above are accurate.', 'nso', 'Ke lekotše ambulense ye le thoto ya yona nna ka noši, gomme dikarabo tše di lego ka godimo di nepagetše.'),
('I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.', 'nso', 'Ke netefatša gore ke lekotše sefatanaga se se lego ka godimo ka mmele gomme tshedimošo ye e ngwadilwego e nepagetše go ya ka tsebo ya ka. Diphošo dife goba dife tše di lemogilwego di swanetše go begelwa mohlokomedi wa kgauswi gomme di ngwalwe pukung ya semmušo ya potleng.'),
('I explained the court date, and that paying the admission of guilt is a conviction and may give a criminal record.', 'nso', 'Ke hlalositše letšatši la kgorotsheko, le gore go lefa kotlo ya go ipona molato ke go ahlolwa gomme go ka fa rekhoto ya bosenyi.'),
('I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).', 'nso', 'Ke hlalositše tsebišo le dikgetho: lefa matšatšing a 32 go hwetša theolelo, dira kgopelo ya go lefa ka dikarolo (AARTO 04), goba o dire boemedi (AARTO 08).'),
('I have an activation code', 'nso', 'Ke na le khoutu ya go thomiša'),
('I have read the POPIA notice (version {POPIA_NOTICE_VERSION})', 'nso', 'Ke badile tsebišo ya POPIA (kgatišo {POPIA_NOTICE_VERSION})'),
('I have read this shift', 'nso', 'Ke badile se šifiting ye'),
('I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.', 'nso', 'Ke tseba ka moo kgoro ya gago e šomago ka gona gomme nka bala boto ya ka nako yeo mošomo wa gago o ka e bonago. Mpotšiše selo sefe goba sefe, goba o mpotše seo ke swanetšego go se dira. Ke a se lokišetša, gomme ga go seo se fetogago go fihlela o netefatša.'),
('I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.', 'nso', 'Ke tseba šifi ya gago, megala ya gago, maikhutšo a gago le didirišwa tša gago. Mpotšiša selo se sengwe le se sengwe ka mošomo wa gago, ka mantšu a gago. Ke a hlaloša le go go bontšha mo o swanetšego go ya; wena o dira mošomo.'),
('I personally completed these checks and confirm that the answers and any defects recorded are accurate.', 'nso', 'Ke phethile ditlhahlobo tše nna ka noši gomme ke netefatša gore dikarabo le diphošo dife goba dife tše di ngwadilwego di nepagetše.'),
('I will use HikTech only for official duties and keep my password private', 'nso', 'Ke tla šomiša HikTech mešomong ya semmušo fela gomme ke boloke lentšu la ka la siphiri le le sephiring'),
