('Official After-Action Reports. Filing one resolves the incident.', 'nso', 'Dipego tša Semmušo tša ka Morago ga Tiro. Go romela e tee go rarolla tiragalo.'),
('Official insignia belong to the municipality and its services, so the platform ships none — upload each department''s real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department''s colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.', 'nso', 'Matšhwao a semmušo ke a mmasepala le ditirelo tša wona, ka gona sethala ga se a tliše — laiša letšhwao la nnete la kgoro ye nngwe le ye nngwe mo gomme le tšwelela gohle gateetee. Go fihla ka nako yeo beche ya ditlhaka tša mathomo e bontšhwa ka mebala ya kgoro yeo, ka gona ga go se se bonagalago se sa fetšwa. PNG goba SVG ye e nago le bokamorago bjo bo bonagalago e šoma kaone; diswantšho tša sekwere di balega gabotse ge di le dinyenyane.'),
